/* Select the immutable rANS table for the active parameter set. */
static const crypto_haetae_rans_table *set_rans_tables(
    const crypto_haetae_parameters *parameters) {
    uint32_t mode = parameters->mode;
    switch (mode) {
        case 2: return &kHAETAETables_Mode2;
        case 3: return &kHAETAETables_Mode3;
        case 5: return &kHAETAETables_Mode5;
        default: return NULL;
    }
}


/*************************************************
 * Name:        crypto_haetae_encode_h
 *
 * Description: rANS encode polynomial vector h
 *
 * Arguments:   - uint8_t  *buf: pointer to output buffer
 *              - const int *h: pointer to polynomial vector h
 **************************************************/
uint16_t crypto_haetae_encode_h(uint8_t  *buf, const int *h, const crypto_haetae_parameters *parameters) {
    size_t size_encoded;
    RansState rans;
    uint8_t  *ptr;
    const size_t haetae_k = parameters->k;
    const size_t size_h = CRYPTO_HAETAE_N * haetae_k;
    uint32_t tmp;
    uint8_t  s;
    uint8_t  encoding[CRYPTO_HAETAE_MAX_HINT_COEFFICIENTS]; // size_h is a loose upper bound
    uint32_t H_CUT;
    size_t i;

    const crypto_haetae_rans_table *T = set_rans_tables(parameters);
    if(!T) {
        return 0;
    }

    H_CUT = (T->m_h - 1) >> 1;

    RansEncInit(&rans);
    ptr = encoding + size_h; // end of encoding buffer

    for (i = size_h; i > 0; i--) {
        tmp = h[i - 1];
        // check for very unlikely values that we do not encode
        // to make the encoding cheaper :
        if(H_CUT < tmp && tmp <= H_CUT + T->offset_h) {
            return 0;
        }
        // map the upper likely part of symbols next to the lower part
        // to have a dense and compact distribution:
        tmp = (tmp > (H_CUT + T->offset_h)) ? tmp - T->offset_h : tmp;
        s = (uint8_t) tmp;

        RansEncPutSymbol(&rans, &ptr, &T->esyms_h[s]);
        // check that at least 4 byte remain for memory safety:
        if (ptr < encoding + 4)
        {
            return 0;
        }
    }

    RansEncFlush(&rans, &ptr);

    size_encoded = encoding + size_h - ptr;
    memcpy(buf, ptr, size_encoded);
    return (uint16_t)size_encoded;
}

/*************************************************
 * Name:        crypto_haetae_decode_h
 *
 * Description: rANS decode polynomial vector h
 *
 * Arguments:   - int *h: pointer to polynomial vector h
 *              - uint8_t  *buf: pointer to output buffer
 **************************************************/
uint16_t crypto_haetae_decode_h(int *h, const uint8_t  *buf, uint16_t size_in, const crypto_haetae_parameters *parameters) {
    size_t size_used;
    RansState rans;
    const size_t haetae_k = parameters->k;
    const size_t size_h = CRYPTO_HAETAE_N * haetae_k;
    uint32_t tmp;
    uint16_t s;
    const uint8_t  *buf_start = buf;
    const uint8_t  *buf_end = buf + size_in;
    size_t i;
    uint32_t H_CUT;

    const crypto_haetae_rans_table *T = set_rans_tables(parameters);
    if(!T) {
        return 0;
    }

    H_CUT = (T->m_h - 1) >> 1;

    if(RansDecInit(&rans, &buf, buf_end)) {
        return 1; // corrupted initial state
    }

    for (i = 0; i < size_h; i++) {
        s = T->symbol_h[RansDecGet(&rans, SCALE_BITS)];
        tmp = (uint32_t) s;
        if(tmp >= T->m_h) {
            return 1; // invalid symbol
        }
        tmp =  (H_CUT < tmp) ? (tmp + T->offset_h) : tmp;
        h[i] = tmp;
        RansDecAdvanceSymbol(&rans, &buf, buf_end, &T->dsyms_h[s], SCALE_BITS);
    }

    if(RansDecVerify(&rans)) {
        return 1; // final state not correct
    }

    size_used = buf - buf_start;
    if(size_used != size_in) {
        return 1; // size does not match
    }
    return 0;
}

/*************************************************
 * Name:        crypto_haetae_encode_hb_z1
 *
 * Description: rANS encode polynomial vector HighBits(z1)
 *
 * Arguments:   - uint8_t  *buf: pointer to output buffer
 *              - const int *hb_z1: pointer to polynomial vector
 *HighBits(z1)
 **************************************************/
uint16_t crypto_haetae_encode_hb_z1(uint8_t  *buf, const int *hb_z1, const crypto_haetae_parameters *parameters) {
    size_t size_encoded;
    RansState rans;
    const size_t haetae_l = parameters->l;
    uint8_t  *ptr;
    const size_t size_hb_z1 = CRYPTO_HAETAE_N * haetae_l;
    uint8_t  s;
    int tmp;
    uint8_t  encoding[CRYPTO_HAETAE_MAX_Z1_COEFFICIENTS]; // size_hb_z1 is a loose upper bound
    size_t i;

    const crypto_haetae_rans_table *T = set_rans_tables(parameters);
    if(!T) {
        return 0;
    }

    RansEncInit(&rans);
    ptr = encoding + size_hb_z1; // end of output buffer

    for (i = size_hb_z1; i > 0; i--) {
        // from centered to positive representation:
        tmp = hb_z1[i - 1] +  T->offset_hb_z1;
        // check for very unlikely values that we do not encode
        // to make the encoding cheaper :
        if (tmp < 0 || (uint32_t)tmp >= T->m_hb_z1) {
            return 0;
        }
        s = (uint8_t) tmp;

        RansEncPutSymbol(&rans, &ptr, &T->esyms_hb_z1[s]);
        // check that at least 4 byte remain for memory safety:
        if (ptr < encoding + 4)
        {
            return 0;
        }
    }
    RansEncFlush(&rans, &ptr);

    size_encoded = encoding + size_hb_z1 - ptr;
    memcpy(buf, ptr, size_encoded);
    return (uint16_t)size_encoded;
}

/*************************************************
 * Name:        crypto_haetae_decode_hb_z1
 *
 * Description: rANS decode polynomial vector HighBits(z1)
 *
 * Arguments:   - int *hb_z1: pointer to polynomial vector HighBits(z1)
 *              - uint8_t  *buf: pointer to output buffer
 **************************************************/
uint16_t crypto_haetae_decode_hb_z1(int *hb_z1, const uint8_t  *buf, uint16_t size_in, const crypto_haetae_parameters *parameters) {
    size_t size_used;
    RansState rans;
    const size_t haetae_l = parameters->l;
    const size_t size_hb_z1 = CRYPTO_HAETAE_N * haetae_l;
    uint32_t tmp;
    uint16_t s;
    const uint8_t  *buf_start = buf;
    const uint8_t  *buf_end = buf + size_in;
    size_t i;

    const crypto_haetae_rans_table *T = set_rans_tables(parameters);
    if(!T) {
        return 0;
    }

    if(RansDecInit(&rans, &buf, buf_end)) {
        return 1; // corrupted initial state
    }

    for (i = 0; i < size_hb_z1; i++) {
        s = T->symbol_hb_z1[RansDecGet(&rans, SCALE_BITS)];
        tmp = (uint32_t) s;
        if(tmp >= T->m_hb_z1) {
            return 1; // invalid symbol
        }
        // from positive to centered representation:
        hb_z1[i] = tmp - T->offset_hb_z1;
        RansDecAdvanceSymbol(&rans, &buf, buf_end, &T->dsyms_hb_z1[s], SCALE_BITS);
    }

    if(RansDecVerify(&rans)) {
        return 1; // final state not correct
    }

    size_used = buf - buf_start;
    if(size_used != size_in) {
        return 1; // size does not match
    }
    return 0;
}
